fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    let mut changes = 0;
    // Only need to iterate through the first half of the array,
    // comparing each element to its mirror at n - 1 - i.
    for i in 0..n / 2 {
        if arr[i] != arr[n - 1 - i] {
            changes += 1;
        }
    }
    changes
}

